24	#define CUDA_CHECK(call)                                                      \
25	    do {                                                                      \
26	        cudaError_t _e = (call);                                              \
27	        if (_e != cudaSuccess) {                                              \
28	            fprintf(stderr, "CUDA error %s at %s:%d\n",                       \
29	                    cudaGetErrorString(_e), __FILE__, __LINE__);              \
