34	static void fillRandom(std::vector<float>& m, unsigned seed) {
35	    std::mt19937 rng(seed);
36	    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
37	    for (auto& x : m) x = dist(rng);
38	}
