72	static double mse(const std::vector<float>& a, const std::vector<float>& b) {
73	    double s = 0.0;
74	    for (size_t i = 0; i < a.size(); ++i) {
75	        const double d = (double)a[i] - (double)b[i];
76	        s += d * d;
77	    }
78	    return s / (double)a.size();
79	}
