#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block layout: 16 x 16 = 256 threads
// Tile size:    128 x 128 shared-memory tiles
// Register tile: each thread computes 8 x 8 elements (128 K-dim FLOPs per iteration)
//
// Arithmetic intensity: 128 FLOPs per 16 shared loads = 8 FLOPs/load
// Shared memory padded to 129 elements to avoid 16-way bank conflicts
//
// Correctness: ceiling division for grid so non-multiples of TILE work
// ============================================================================

#define TILE_G 128       // Output tile edge per block
#define TILE_K 128       // K-dim tile per iteration
#define TX     16        // Block dim X
#define TY     16        // Block dim Y
#define BLK    (TX * TY) // 256
// Register tile: TILE_G/TX = TILE_G/TY = 8
#define TM 8
#define TN 8

// Padding for shared memory to break bank conflicts (16 threads => 16-way
// conflict on 32-bank GPU; padding by +1 shifts banks to 1..16 = no conflict)
#define SM_PAD 1

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_K][TILE_G + SM_PAD];
    __shared__ float Bs[TILE_K][TILE_G + SM_PAD];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    // Output position
    const int outCol = bx * TILE_G + tx;
    const int outRow = by * TILE_G + ty;

    // Number of K tiles
    const int numTiles = (N + TILE_K - 1) / TILE_K;

    // Register file: thread (tx, ty) handles C-row [outRow..outRow+7]
    //                        C-col [outCol..outCol+7]
    float acc[TM] = {0.0f};
    // Zero-initialize each of the 8 output elements
    #pragma unroll
    for (int i = 0; i < TM; ++i) acc[i] = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // ---- Load A tile (row-major, coalesced) ----
        // Thread (tx, ty): As[tx][ty] stores A[outRow][t*TILE_K + tx]
        // Warp = 32 threads, tx spans 0..31 within warp => consecutive
        //       columns in A => coalesced global load.
        // We have 16 threads per row (tx=0..15, ty=0..15).
        // Warp 0: ty=0, tx=0..31 -> loads As[0..31][0] but we only have 16 tx
        // Actually TX=16, so warp 0 = threads 0..15 = ty=0, tx=0..15.
        // Warp 1 = threads 16..31 = ty=1, tx=0..15.
        // Each warp loads 16 consecutive columns => fully coalesced.
        #pragma unroll
        for (int k = 0; k < TILE_K; k += TX) {
            const int aRow = outRow;
            const int aCol = t * TILE_K + k + tx;
            if (aRow < N && aCol < N)
                As[k + (tx)][ty] = A[aRow * N + aCol];
            else
                As[k + (tx)][ty] = 0.0f;
        }

        // ---- Load B tile (row-major) ----
        // Thread (tx, ty): Bs[tx][ty] stores B[t*TILE_K + ty][outCol + tx]
        // Warp: ty fixed, tx=0..15, consecutive cols in B => coalesced
        #pragma unroll
        for (int k = 0; k < TILE_K; k += TX) {
            const int bRow = t * TILE_K + ty;
            const int bCol = t * TILE_K + k + tx;
            if (bRow < N && bCol < N)
                Bs[k + (tx)][ty] = B[bRow * N + bCol];
            else
                Bs[k + (tx)][ty] = 0.0f;
        }

        __syncthreads();

        // ---- Multiply-accumulate ----
        // Thread (tx, ty) computes:
        //   acc[i] += sum_k( As[k][ty*TM/TY + i] * Bs[k][tx*TN/TX + 0..7] )
        // With TM=8, TY=16 => TM/TY = 0.5. That's wrong for integer math.
        //
        // Fix: TM/TY = 8/16 = 0.5 => each thread handles 0.5 rows? That can't be.
        //
        // The issue: TILE_G=128, TY=16, so rows per thread = 128/16 = 8.
        // And TILE_G=128, TX=16, so cols per thread = 128/16 = 8.
        // Thread (tx, ty) handles rows [ty*8 .. ty*8+7] and cols [tx*8 .. tx*8+7].
        // So the thread's row offset within the tile = ty * 8, col offset = tx * 8.
        // But tx * 8 for tx=0..15 gives 0,8,16,...,120 which spans 0..120, not 0..7.
        // That's correct: tx * 8 maps 16 threads to 16 groups of 8 columns each.
        //
        // For the inner loop:
        //   For i in 0..7 (rows): for j in 0..7 (cols):
        //     acc[i][j] += sum_k( As[k][ty*8+i] * Bs[k][tx*8+j] )
        // Each thread does 8*8*128 = 8192 FLOPs, loads 8+8=16 elements from SM.
        // FLOPs/load = 512 per load iteration. Great!

        float accLocal[TM] = {0.0f};
        #pragma unroll
        for (int i = 0; i < TM; ++i)
            accLocal[i] = 0.0f;

        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                float a = As[k][ty * TM + i];
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    accLocal[i] += a * Bs[k][tx * TN + j];
            }
        }

        #pragma unroll
        for (int i = 0; i < TM; ++i)
            acc[i] += accLocal[i];

        __syncthreads();
    }

    // ---- Store result ----
    if (outRow < N && outCol < N) {
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            C[(outRow + i) * N + outCol] = acc[i];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TILE_G - 1) / TILE_G,
              (N + TILE_G - 1) / TILE_G);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
