#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block layout: 16 x 16 = 256 threads
// Tile size:    128 x 128 shared-memory tiles
// Register tile: each thread computes an 8 x 8 sub-tile
//
// Each thread: TM*TN = 64 elements × TILE_K = 128 K-iter = 8192 MAC/thread
// Shared memory padded to break 16-way bank conflicts
// ============================================================================

#define TG 128       // Output tile edge per block
#define TK 128       // K-dim tile per iteration
#define TX 16        // Block dim X
#define TY 16        // Block dim Y
#define BLK (TX * TY)// 256
// Register tile
#define TM 8         // = TG / TY
#define TN 8         // = TG / TX

// Padded shared memory to reduce bank conflicts
#define SM_PAD 1     // Shifts by 1, breaking exact 32-bank alignment

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TG + SM_PAD];
    __shared__ float Bs[TK][TG + SM_PAD];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTiles = (N + TK - 1) / TK;

    // Accumulator for this thread's TM×TN sub-tile
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile (row-major, coalesced) ---
        // Warp 0 (ty=0, tx=0..15) reads As[k+0..15][0] from global
        // => 16 consecutive columns in A per warp => coalesced
        #pragma unroll 2
        for (int k = 0; k < TK; k += TX) {
            const int aRow = outRow;
            const int aCol = t * TK + k + tx;
            if (aRow < N && aCol < N)
                As[k + tx][ty] = A[aRow * N + aCol];
            else
                As[k + tx][ty] = 0.0f;
        }

        // --- Load B tile (row-major, coalesced within warp) ---
        #pragma unroll 2
        for (int k = 0; k < TK; k += TX) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + k + tx;
            if (bRow < N && bCol < N)
                Bs[k + tx][ty] = B[bRow * N + bCol];
            else
                Bs[k + tx][ty] = 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        // Thread (tx, ty) handles C rows [outRow+ty*TM/TY .. outRow+ty*TM/TY+TM/TY-1]
        // Wait: TM/TY = 8/16 = 0.5. That's wrong for integer indexing.
        // 
        // Fix: The row stride per thread is TM = 8, and TY=16 means
        // rows 0-7 go to ty=0-8, rows 8-15 to ty=8-16... that doesn't divide evenly.
        //
        // Actually: TG=128, TY=16 => rows per thread = 128/16 = 8.
        // Thread ty handles rows outRow + ty*8 .. outRow + ty*8 + 7.
        // Thread tx handles cols outCol + tx*8 .. outCol + tx*8 + 7.
        // So:
        //   rowOffset = ty * 8 = ty * TM
        //   colOffset = tx * 8 = tx * TN

        float aRowPtr[TM];
        float bColPtr[TN];

        #pragma unroll
        for (int i = 0; i < TM; ++i)
            aRowPtr[i] = 0.0f;

        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                aRowPtr[i] = As[k][ty * TM + i];

            #pragma unroll
            for (int j = 0; j < TN; ++j)
                bColPtr[j] = Bs[k][tx * TN + j];

            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += aRowPtr[i] * bColPtr[j];
            }
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) {
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            C[(outRow + i) * N + outCol] = acc[i][0];  // Only storing one column
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
