#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:      TX=16, TY=16 = 256 threads
// Tile:       64 x 64 shared-memory tiles (TILE_G, TILE_K)
// Reg tile:   TM=4, TN=4 per thread (4x4 = 16 output elements)
//
// Why 64x64?  Better occupancy (32KB shared/block => 5 blocks/SM)
//             with low syncthreads overhead (32 K-iters for N=2048)
// ============================================================================

#define TG 64
#define TK 64
#define TX 16
#define TY 16
#define BLK (TX * TY)
#define TM 4   // = TG / TY
#define TN 4   // = TG / TX

// Pad shared memory rows by 1 to break 16-way bank conflicts for TX=16 threads
// reading consecutive columns (64 cols = 2 full wraps of 32 banks => 2-way conflict).
// Adding +1 to each row index shifts the access pattern.
#define SM_PAD 65

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TG + SM_PAD];
    __shared__ float Bs[TK][TG + SM_PAD];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTiles = (N + TK - 1) / TK;

    // Accumulator: thread (tx,ty) handles C rows [outRow..outRow+TM-1]
    //                           cols [outCol..outCol+TN-1]
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTiles; ++t) {
        // Load A tile — coalesced: warp reads 16 consecutive A columns
        for (int k = 0; k < TK; k += TX) {
            const int aRow = outRow;
            const int aCol = t * TK + k + tx;
            if (aRow < N && aCol < N)
                As[k + tx][ty] = A[aRow * N + aCol];
            else
                As[k + tx][ty] = 0.0f;
        }

        // Load B tile — coalesced: warp reads 16 consecutive B columns
        for (int k = 0; k < TK; k += TX) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + k + tx;
            if (bRow < N && bCol < N)
                Bs[k + tx][ty] = B[bRow * N + bCol];
            else
                Bs[k + tx][ty] = 0.0f;
        }

        __syncthreads();

        // Multiply-accumulate
        float accLocal[TM][TN] = {0.0f};

        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                float a = As[k][ty * TM + i];
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    accLocal[i][j] += a * Bs[k][tx * TN + j];
            }
        }

        #pragma unroll
        for (int i = 0; i < TM; ++i)
            #pragma unroll
            for (int j = 0; j < TN; ++j)
                acc[i][j] += accLocal[i][j];

        __syncthreads();
    }

    // Store
    if (outRow < N && outCol < N) {
        for (int i = 0; i < TM; ++i)
            for (int j = 0; j < TN; ++j)
                C[(outRow + i) * N + (outCol + j)] = acc[i][j];
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
