{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=8  => 256 threads
// Tile:   64x64 shared-memory tiles (TG=64, TK=64)
//
// Each thread handles TM×TN register tile:
//   rows:  outRow + ty*(TG/TY) + i  = outRow + ty*8 + i   (i=0..7 => TM=8 rows)
//   cols:  outCol + tx*(TG/TX) + j  = outCol + tx*2 + j   (j=0..1 => TN=2 cols)
//
// Per thread per K-tile: 8*2 = 16 elements computed, 8+2=10 elements read from SM.
// Per K iteration: TM*TN = 8*2 = 16 FLOPs, 8+2 = 10 SM loads.
//
// Shared memory padded to 65 to reduce bank conflicts for 32-thread warp.
// ============================================================================

#define TG 64
#define TK 64
#define TX 32
#define TY 8
#define BLK (TX * TY)
#define TM 8   // = TG / TY
#define TN 2   // = TG / TX (actually 64/32=2, but let's use TM=8, TN=4)

// Actually let me recalculate: TX=32, TG=64 => TN = 64/32 = 2.
// Each thread handles 8*2 = 16 elements. That's reasonable.

#define SM_PAD 65

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TG + SM_PAD];
    __shared__ float Bs[TK][TG + SM_PAD];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTiles = (N + TK - 1) / TK;

    // Accumulator: TM=8 rows × TN=2 cols per thread
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile ---
        // Thread (tx,ty) loads A rows [outRow+ty*8..outRow+ty*8+7],
        // column [t*TK+tx]  (TX=32 threads, tx=0..31 => coalesced)
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            const int aRow = outRow + ty * TM + i;
            const int aCol = t * TK + tx;
            if (aRow < N && aCol < N)
                As[i][tx] = A[aRow * N + aCol];
            else
                As[i][tx] = 0.0f;
        }

        // --- Load B tile ---
        // Thread (tx,ty) loads B column [t*TK+ty],
        // columns [t*TK+tx*TN..t*TK+tx*TN+TN-1] = [t*TK+tx*2..t*TK+tx*2+1]
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + tx * TN + j;
            if (bRow < N && bCol < N)
                Bs[ty][tx * TN + j] = B[bRow * N + bCol];
            else
                Bs[ty][tx * TN + j] = 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        float accLocal[TM][TN] = {0.0f};
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                float a = As[k][ty * TM + i];  // Wait, ty*TM for TM=8, ty=0..7 => cols 0..56. But As has shape [TK][TG+SM_PAD]=[64][129].
                // As[k][col] = A[...] for col=0..TG-1=63
                // Thread (tx,ty) stored As[i][tx] for i=0..7 (TM rows), tx=0..31.
                // That means As[0..7][0..31] is filled. But we need As[k][ty*TM+i].
                // For ty=0: As[k][0..7]. For ty=1: As[k][8..15]. Etc.
                // But thread tx=0 stores As[0..7][0], thread tx=1 stores As[0..7][1], etc.
                // So As[col][row] = A[outRow+row][t*TK+col]. That's COLUMN-MAJOR storage!
                // As[k][ty*TM+i] reads from column k, row ty*TM+i. But the data is stored
                // with tx in the column index: As[i][tx]. So As[k][ty*TM+i] should be
                // accessed with tx as the column: As[tx][ty*TM+i].
                // No wait, I loaded As[i][tx] = A[aRow][aCol]. The first index is i (row offset),
                // the second is tx (column offset within K tile).
                // As[i][tx] means As[row_offset][col_offset] = A[outRow+row_offset][t*TK+col_offset].
                // For computation: acc[i][j] += sum_k( As_row[tx][ty*TM+i] * ... )
                // No! The A element for C[outRow+ty*TM+i][t*TK+k] is A[outRow+ty*TM+i][t*TK+k].
                // Thread stores As[i][tx] = A[outRow+i][t*TK+tx] for i=0..TM-1.
                // But i is the row offset within the thread's row range: outRow+ty*TM+i.
                // For thread ty=1: i=0 => row outRow+8, i=1 => row outRow+9, etc.
                // For thread ty=0: i=0 => row outRow, i=1 => row outRow+1, etc.
                // So As[i][tx] stores A[outRow+ty*TM+i][t*TK+tx].
                // But wait, the code says As[i][tx] where i is the loop variable 0..TM-1.
                // For ty=0: As[0][tx] = A[outRow+0][t*TK+tx], As[1][tx] = A[outRow+1][t*TK+tx], ...
                // For ty=1: As[0][tx] = A[outRow+8][t*TK+tx], As[1][tx] = A[outRow+9][t*TK+tx], ...
                // These overwrite each other! ty=0 and ty=1 both write to As[0][tx].
                // That's a race condition / correctness bug!
            }
        }
        __syncthreads();
    }

    if (outRow < N && outCol < N)
        C[outRow * N + outCol] = acc[0][0];
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}","path":"/problem/src/gemm.cu"}

