#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=8   => 256 threads
// Tile:   64x64 shared-memory tiles
//
// Each thread (tx,ty) computes a single output element:
//   C[by*64+ty][bx*64+tx] = sum_k A[by*64+ty][k] * B[k][bx*64+tx]
//
// Shared memory layout (row-major):
//   As[tILE_K][TILE_G]  -- tile of A, row-major
//   Bs[tILE_K][TILE_G]  -- tile of B, row-major
//
// Coalesced global loads:
//   A: warp (32 threads in X) loads 32 consecutive columns of one row => coalesced
//   B: warp loads 32 consecutive columns for one row => coalesced
//
// Shared memory access: As[ty][k] and Bs[k][tx] -- each thread accesses a
// single row of As (stride 1) and a single column of Bs (stride 1) => coalesced
// within the warp (32 threads sharing same ty).
// ============================================================================

#define TG 64
#define TK 64
#define TX 32
#define TY 8
#define BLK (TX * TY)

__device__ float2 load2_coalesced(const float* __restrict__ ptr) {
    const float2* p = (const float2*)(ptr);
    return *p;
}

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TG];
    __shared__ float Bs[TK][TG];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTiles = (N + TK - 1) / TK;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile ---
        // Warp-level coalesced: 32 threads (tx=0..31) read 32 consecutive columns
        // Each thread loads 2 floats for better memory utilization
        for (int k = 0; k < TK; k += 2) {
            const int aCol = t * TK + k + tx;
            if (outRow < N && aCol < N)
                ((float2*)As[k])[tx] = ((float2*)A[outRow * N + t * TK + k])[tx];
            else {
                As[k][tx] = 0.0f;
                As[k + 1][tx] = 0.0f;
            }
        }

        // --- Load B tile ---
        // Warp-level coalesced for each row
        for (int k = 0; k < TK; k += 2) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + k + tx;
            if (bRow < N && bCol < N)
                ((float2*)Bs[k])[tx] = ((float2*)B[bRow * N + t * TK + k])[tx];
            else {
                Bs[k][tx] = 0.0f;
                Bs[k + 1][tx] = 0.0f;
            }
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k)
            acc += As[k][ty] * Bs[k][tx];

        __syncthreads();
    }

    if (outRow < N && outCol < N)
        C[outRow * N + outCol] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
