#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=8   => 256 threads
// Tile:   64x64 shared-memory tiles
//
// Each thread (tx,ty) computes C[by*64+ty][bx*64+tx] = sum_k A[...][k]*B[k][...]
//
// As[tILE_K][TILE_G] and Bs[tILE_K][TILE_G], row-major in shared memory.
//
// Global loads: coalesced (32 threads = 1 warp read consecutive elements).
// Shared memory reads: As[ty][k] broadcast to 32 threads, Bs[k][tx] coalesced.
// ============================================================================

#define TG 64
#define TK 64
#define TX 32
#define TY 8

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TG];
    __shared__ float Bs[TK][TG];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTiles = (N + TK - 1) / TK;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile (row-major, coalesced) ---
        for (int k = 0; k < TK; ++k) {
            const int aCol = t * TK + k;
            if (outRow < N && aCol < N)
                As[k][tx] = A[outRow * N + aCol];
            else
                As[k][tx] = 0.0f;
        }

        // --- Load B tile (row-major, coalesced) ---
        for (int k = 0; k < TK; ++k) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + k + tx;
            if (bRow < N && bCol < N)
                Bs[k][tx] = B[bRow * N + bCol];
            else
                Bs[k][tx] = 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k)
            acc += As[k][ty] * Bs[k][tx];

        __syncthreads();
    }

    if (outRow < N && outCol < N)
        C[outRow * N + outCol] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
