#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads
// Tile:   64x64 shared-memory tiles
//
// Each thread handles 2x2 = 4 output elements (register tiling).
// Thread (tx,ty) computes C rows [outRow..outRow+1] cols [outCol..outCol+1].
//
// Shared memory: As[TK][TG] row-major, Bs[TK][TG] row-major.
// Coalesced loads via warp-level cooperation.
// ============================================================================

#define TG 64
#define TK 64
#define TX 32
#define TY 32
#define BLK (TX * TY)  // 1024
#define TM 2   // = TG / TY
#define TN 2   // = TG / TX

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TG];
    __shared__ float Bs[TK][TG];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTiles = (N + TK - 1) / TK;

    // Accumulator: 2 rows × 2 cols per thread
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile ---
        // Each thread tx loads A row [outRow+ty*TM..outRow+ty*TM+TM-1],
        // columns [t*TK+tx]. With TX=32, 32 threads load 32 consecutive
        // columns => coalesced within warp.
        for (int k = 0; k < TK; ++k) {
            const int aCol = t * TK + tx;
            for (int i = 0; i < TM; ++i) {
                const int aRow = outRow + ty * TM + i;
                if (aRow < N && aCol < N)
                    As[k][ty * TM + i] = A[aRow * N + aCol];
                else
                    As[k][ty * TM + i] = 0.0f;
            }
        }

        // --- Load B tile ---
        // Thread tx loads B row [t*TK+ty], columns [t*TK+tx*TN..t*TK+tx*TN+TN-1]
        for (int k = 0; k < TK; ++k) {
            const int bRow = t * TK + ty;
            for (int j = 0; j < TN; ++j) {
                const int bCol = t * TK + tx * TN + j;
                if (bRow < N && bCol < N)
                    Bs[k][tx * TN + j] = B[bRow * N + bCol];
                else
                    Bs[k][tx * TN + j] = 0.0f;
            }
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        float accLocal[TM][TN] = {0.0f};
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                float a = As[k][ty * TM + i];
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    accLocal[i][j] += a * Bs[k][tx * TN + j];
            }
        }

        #pragma unroll
        for (int i = 0; i < TM; ++i)
            #pragma unroll
            for (int j = 0; j < TN; ++j)
                acc[i][j] += accLocal[i][j];

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) {
        for (int i = 0; i < TM; ++i)
            for (int j = 0; j < TN; ++j)
                C[(outRow + i) * N + (outCol + j)] = acc[i][j];
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
