// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads (max occupancy)
// Tile:   32x32 shared-memory tiles
//
// Each thread computes ONE output element: C[by*32+ty][bx*32+tx]
// = sum_{k=0}^{31} A[by*32+ty][bx*32+k] * B[bx*32+k][bx*32+tx]
//
// Shared memory: As[32][32], Bs[32][32] — row-major, padded for L2 alignment
//
// Global loads: fully coalesced (32 threads = 1 warp, consecutive addresses)
// Shared reads: broadcast (As[ty][k]) and coalesced (Bs[k][tx])
// ============================================================================

#define TILE 32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    // Padded to avoid L2 bank conflict issues on 64-byte boundaries
    __shared__ float As[TILE][TILE + 1];
    __shared__ float Bs[TILE][TILE + 1];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outRow = by * TILE + ty;
    const int outCol = bx * TILE + tx;
    const int numTiles = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile into shared memory ---
        // Warp (ty=const, tx=0..31) reads TILE consecutive A elements
        // => fully coalesced global load
        As[ty][tx] = (outRow < N && (t * TILE + tx) < N)
                    ? A[outRow * N + t * TILE + tx] : 0.0f;

        // --- Load B tile into shared memory ---
        // Warp (ty=const, tx=0..31) reads TILE consecutive B elements
        // => fully coalesced global load
        Bs[ty][tx] = ((t * TILE + ty) < N && outCol < N)
                    ? B[(t * TILE + ty) * N + t * TILE + tx] : 0.0f;

        __syncthreads();

        // --- Multiply-accumulate ---
        // As[ty][k] is broadcast to all 32 threads in the warp (same ty, different tx)
        // Bs[k][tx] is coalesced within the warp (same k, different tx = consecutive)
        #pragma unroll
        for (int k = 0; k < TILE; ++k)
            acc += As[ty][k] * Bs[k][tx];

        __syncthreads();
    }

    if (outRow < N && outCol < N)
        C[outRow * N + outCol] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TILE, TILE);  // 32 x 32 = 1024
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
