// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads
// Tile:   64x64 shared-memory tiles
// Register tile: TM=4, TN=4 (each thread computes 4×4 = 16 output elements)
// K-tile size: 16 (4 K-steps per block for N=64)
//
// As[TK+TX][TM*TY] — padded for bank conflicts
// Bs[TK][TN*TX] — padded for bank conflicts
//
// Each thread loads TM elements from A and TN elements from B per K iteration,
// giving TM*TN = 16 MACs per iteration. 4 K-tiles per block.
//
// Total MACs per block: 256 threads × 16 MACs/tile × 4 tiles = 16384.
// Output tile size: 64×64 = 4096 elements × 64 MACs = 262144.
// ============================================================================

#define TG 64        // Output tile size
#define TK 16        // K-tile size (number of K values per sync)
#define TX 16        // Block dim X
#define TY 16        // Block dim Y
#define TM 4         // = TG / TY (rows per thread)
#define TN 4         // = TG / TX (cols per thread)
#define NUM_TILES_K (TG / TK)  // = 4

// Shared memory: padded to reduce bank conflicts
// As: TM*TY rows × (TK+TX) cols = 64 × 32
// Bs: (TK+TX) rows × TN*TX cols = 32 × 64
__align__(64)
__shared__ float As[TK + TX][TM * TY];  // 32 × 64 = 8KB
__align__(64)
__shared__ float Bs[TK + TX][TN * TX];  // 32 × 64 = 8KB

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: 4×4 elements per thread
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile ---
        // Thread (tx,ty) loads A rows [outRow..outRow+TM-1],
        // column [t*TK+tx]  (TX=16 threads, 1 column each = 16 cols per warp)
        for (int i = 0; i < TM; ++i) {
            const int aRow = outRow + ty * TM + i;
            const int aCol = t * TK + tx;
            if (aRow < N && aCol < N)
                As[k_idx(tx, i)][ty_idx(ty, i)] = A[aRow * N + aCol];
            else
                As[k_idx(tx, i)][ty_idx(ty, i)] = 0.0f;
        }

        // --- Load B tile ---
        for (int j = 0; j < TN; ++j) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + tx * TN + j;
            if (bRow < N && bCol < N)
                Bs[k_idx_b(tx, j)][ty_idx_b(ty)] = B[bRow * N + bCol];
            else
                Bs[k_idx_b(tx, j)][ty_idx_b(ty)] = 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        // As[k+tx][ty*TM+i] = A[outRow+ty*TM+i][t*TK+k+tx]
        // Bs[k+tx][ty*TN+j] = B[t*TK+ty][t*TK+k+tx*TN+j]
        // Wait, the indices don't match up. Let me rethink.

        for (int k = 0; k < TK; ++k) {
            for (int i = 0; i < TM; ++i) {
                float a = As[k + tx][ty * TM + i];
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += a * Bs[k + tx][tx * TN + j];
            }
        }

        __syncthreads();
    }

    if (outRow < N && outCol < N) {
        for (int i = 0; i < TM; ++i)
            for (int j = 0; j < TN; ++j)
                C[(outRow + i) * N + (outCol + j)] = acc[i][j];
    }
}

__device__ inline int k_idx(int tx, int i) { return tx; }
__device__ inline int ty_idx(int ty, int i) { return ty * TM + i; }
__device__ inline int k_idx_b(int tx, int j) { return tx * TN + j; }
__device__ inline int ty_idx_b(int ty) { return ty; }

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
