// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads
// Tile:   32x32 shared-memory tiles
//
// Global loads: fully coalesced (one warp = one row of 32 elements).
// Shared reads: As[ty][k] broadcast to 32 threads, Bs[k][tx] coalesced.
//
// Performance tuning:
// - 2 K-iterations per synchronization to reduce sync overhead
// - Unrolled K loop for better ILP
// - __restrict__ pointers for compiler optimization
// ============================================================================

#define TILE 32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TILE + tx;
    const int outRow = by * TILE + ty;
    const int numTiles = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; t += 2) {
        // --- Load A tile for K-tile t ---
        As[ty][tx] = (outRow < N && (t * TILE + tx) < N)
                    ? A[outRow * N + t * TILE + tx] : 0.0f;
        // --- Load B tile for K-tile t ---
        Bs[ty][tx] = ((t * TILE + ty) < N && outCol < N)
                    ? B[(t * TILE + ty) * N + outCol] : 0.0f;

        if (t + 1 < numTiles) {
            // --- Load A tile for K-tile t+1 ---
            As[ty][tx] = (outRow < N && ((t + 1) * TILE + tx) < N)
                        ? A[outRow * N + (t + 1) * TILE + tx] : 0.0f;
            // --- Load B tile for K-tile t+1 ---
            Bs[ty][tx] = (((t + 1) * TILE + ty) < N && outCol < N)
                        ? B[((t + 1) * TILE + ty) * N + outCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate K-tile t ---
        #pragma unroll
        for (int k = 0; k < TILE; ++k)
            acc += As[ty][k] * Bs[k][tx];

        if (t + 1 < numTiles) {
            __syncthreads();
            // --- Multiply-accumulate K-tile t+1 ---
            #pragma unroll
            for (int k = 0; k < TILE; ++k)
                acc += As[ty][k] * Bs[k][tx];
        }
    }

    if (outRow < N && outCol < N)
        C[outRow * N + outCol] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
