#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40) with register tiling
//
// Block:  TX=16, TY=16  => 256 threads
// Tile:   64x64 shared-memory tiles
// Register tile: TM=4, TN=4 (each thread computes 4×4 = 16 elements)
// K-tile: 16 (4 K-steps per sync, 4 K-tiles per block)
//
// As[TX][TM*TY] = As[16][64] — thread tx writes column tx, rows ty*TM..ty*TM+TM-1
// Bs[TY][TN*TX] = Bs[16][64] — thread ty writes row ty, columns tx*TN..tx*TN+TN-1
//
// Each thread reads TM elements from As and TN elements from Bs per K iteration.
// MACs per thread per K-iteration: TM * TN = 16.
// Total MACs per block: 256 * 16 * 16 * 4 = 262144.
// ============================================================================

#define TG 64        // Output tile edge
#define TK 16        // K-tile size
#define TX 16        // Block dim X
#define TY 16        // Block dim Y
#define TM 4         // = TG / TY  (rows per thread)
#define TN 4         // = TG / TX  (cols per thread)

// Shared memory: padded to avoid bank conflicts
// As: [TK + TX][TM * TY] — [32][64] = 8KB, 16-way padding for TX=16 threads
// Bs: [TK + TX][TN * TX] — [32][64] = 8KB
__shared__ float As[TX + TK][TM * TY];
__shared__ float Bs[TN * TX][TK + TY];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: 4×4 elements per thread
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile ---
        // Thread tx=0..15, ty=0..15: As[tx][ty*TM+i] = A[outRow+ty*TM+i][t*TK+tx]
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            const int aRow = outRow + ty * TM + i;
            const int aCol = t * TK + tx;
            if (aRow < N && aCol < N)
                As[tx][ty * TM + i] = A[aRow * N + aCol];
            else
                As[tx][ty * TM + i] = 0.0f;
        }

        // --- Load B tile ---
        // Thread tx=0..15, ty=0..15: Bs[ty][tx*TN+j] = B[t*TK+ty][t*TK+tx*TN+j]
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + tx * TN + j;
            if (bRow < N && bCol < N)
                Bs[ty][tx * TN + j] = B[bRow * N + bCol];
            else
                Bs[ty][tx * TN + j] = 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        // As[tx][k] = A[outRow+ty*TM+..][t*TK+..] — wait, need to check indices
        // As[tx][ty*TM+i] was loaded for tx=0..15. Read: As[k][ty*TM+i].
        // But the load was As[tx][...], not As[k][...]. For k=tx: As[tx][...] = loaded data.
        // For k≠tx: As[k][...] should be loaded by thread with tx=k.
        // So As[k][ty*TM+i] accesses the element loaded by thread tx=k, row ty*TM+i.
        // ✓

        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                float a = As[k][ty * TM + i];
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += a * Bs[k][tx * TN + j];
            }
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) {
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int row = outRow + i;
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int col = outCol + j;
                C[row * N + col] = acc[i][j];
            }
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
