{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads
// Tile:   64x64 shared-memory tiles
// Register tile: TM=4, TN=4 (each thread computes 4×4 = 16 output elements)
//
// Correct approach: simple sync before each K-tile compute.
//
// Shared memory layout:
//   As[TK][TM*TY+TX] = As[TK][64+16] = As[TK][80] — padded for bank conflicts
//   Bs[TK][TN*TX+TY] = As[TK][64+16] = As[TK][80]
//
// Each thread (tx, ty) handles:
//   rows: outRow + ty*TM .. outRow + ty*TM + TM-1
//   cols: outCol + tx*TN .. outCol + tx*TN + TN-1
//
// Loading:
//   Thread tx=0..15, ty=0..15:
//   As[k + tx][ty*TM + i] = A[outRow + ty*TM + i][t*TK + k + tx]
//   Wait, this stores A column k+tx for each tx. For tx=0..15, that's 16 consecutive
//   columns. So As column 0..15 is filled by threads tx=0..15 respectively.
//   The row is ty*TM+i for ty=0..15, i=0..3 => rows 0..63.
//   So As[k+tx][ty*TM+i] = A[outRow+ty*TM+i][t*TK+k+tx]... but that means
//   As column is (ty*TM+i) which ranges 0..63. And As row is (k+tx) which ranges 0..31.
//   That's wrong — As is only 80 columns wide and we need it to be 64+ wide.
//   
// Let me use a simpler layout.
// ============================================================================

#define TG 64        // Output tile edge
#define TK 16        // K-tile size (16 K values per sync)
#define TX 16        // Block dim X
#define TY 16        // Block dim Y
#define TM 4         // = TG / TY  (rows per thread)
#define TN 4         // = TG / TX  (cols per thread)

// Shared memory: As and Bs, padded to avoid bank conflicts
// As[TG][TG] with padding: [TK+TX][TM*TY+TX] — hmm this is getting complicated.
// Let me just use a straightforward 2D array layout with padding.

#define SM_COLS_A (TG + TX)  // 64 + 16 = 80
#define SM_ROWS_B (TG + TY)  // 64 + 16 = 80

__shared__ float As[TK][SM_COLS_A];  // [16][80]
__shared__ float Bs[SM_ROWS_B][TK];  // [80][16]

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: 4×4 elements per thread
    float acc[TM][TN] = {0.0f};

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile ---
        // Thread (tx, ty) loads: A[outRow + ty*TM + i][t*TK + tx] for i=0..3
        // But each thread only loads 16 elements per K-tile (one from each tx=0..15).
        // So thread (tx,ty) loads from columns t*TK+tx only.
        // As[tx][ty*TM+i] = A[outRow+ty*TM+i][t*TK+tx]
        // As is [TK][SM_COLS_A] = [16][80], indexed as As[k][col].
        // Here tx ranges 0..15, so As row = tx (0..15), col = ty*TM+i (0..63).
        // That means As[tx][ty*TM+i] stores column tx of the A tile.
        // With TX=16 threads and SM_COLS_A=80, this has enough columns.
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            const int aRow = outRow + ty * TM + i;
            const int aCol = t * TK + tx;
            if (aRow < N && aCol < N)
                As[tx][ty * TM + i] = A[aRow * N + aCol];
            else
                As[tx][ty * TM + i] = 0.0f;
        }

        // --- Load B tile ---
        // Thread (tx, ty) loads: B[t*TK+ty][t*TK + tx*TN + j] for j=0..3
        // Bs[SM_ROWS_B][TK] = Bs[80][16], indexed as Bs[row][k].
        // Here ty ranges 0..15, so Bs row = ty (0..15), k = tx*TN+j (0..60).
        // With SM_ROWS_B=80 and TK=16, this has enough rows.
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int bRow = t * TK + ty;
            const int bCol = t * TK + tx * TN + j;
            if (bRow < N && bCol < N)
                Bs[ty][tx * TN + j] = B[bRow * N + bCol];
            else
                Bs[ty][tx * TN + j] = 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        // Thread (tx, ty) reads:
        //   As[tx][ty*TM+i] for i=0..3 — this is a row access in As
        //   Bs[tx*TN+j][tx] — wait, I stored Bs[ty][tx*TN+j], not Bs[tx*TN+j][ty].
        //   The B element at row (t*TK+ty) and column (t*TK+k+tx*TN+j) is stored as
        //   Bs[ty][tx*TN+j] for tx=0..15. But for computation, I need Bs[k+tx][...] 
        //   or similar.
        //
        // Actually, the B tile for K-tile t has columns t*TK..t*TK+63.
        // Thread tx=0 loads B[t*TK+ty][t*TK+0..3] = Bs[ty][0..3]
        // Thread tx=1 loads B[t*TK+ty][t*TK+4..7] = Bs[ty][4..7]
        // So Bs[ty][tx*TN+j] = B[t*TK+ty][t*TK+tx*TN+j]
        //
        // For K iteration k (0..15), I need B[t*TK+ty][t*TK+k+tx*TN+j].
        // But I only loaded Bs[ty][tx*TN+j] = B[t*TK+ty][t*TK+tx*TN+j],
        // which is for k=0 only! I need to load all 16 K iterations.
        //
        // I see the problem: each thread only loads 1 column from B (tx*TN+j).
        // For k=0, that's column tx*TN+j. For k=1, that's column tx*TN+j+16.
        // But I haven't loaded columns tx*TN+j+16..tx*TN+j+31!
        //
        // Fix: each thread needs to load 4 B columns per K iteration, across all 16 K iterations.
        // That's 4*16 = 64 elements per thread from B.
        // With SM_ROWS_B=80 and TK=16, I can store Bs[80][16].
        // Thread (tx,ty): Bs[ty + k*TY][tx*TN+j]? That would be 80 rows and 16 columns.
        // But then Bs[k*TY+ty][tx*TN+j] = B[t*TK+k*TY+ty][t*TK+k*TY+tx*TN+j].
        // That's 16 K iterations, each with TY=16 rows. But the B tile only has 16 rows
        // (t*TK..t*TK+15), not 256!
        //
        // OK, I'm overcomplicating this. Let me just use the correct shared memory layout.

        for (int k = 0; k < TK; ++k) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                float a = As[tx][ty * TM + i];
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    // Need: Bs[t*TK+ty][t*TK+k+tx*TN+j]
                    // Stored in Bs[...] — need to figure out where.
                    // Bs[ty][tx*TN+j] = B[t*TK+ty][t*TK+tx*TN+j] — only for k=0.
                    // For general k, the element is Bs[ty][tx*TN+j+tx*TN... no.
                    // Bs has layout Bs[80][16]. The loaded elements are:
                    // Bs[ty][tx*TN+j] for j=0..3, which is Bs[ty][0..60] in steps of 4.
                    // But I need all k=0..15 iterations.
                    //
                    // I should load Bs[k][ty][...] somehow. But Bs only has 2 dimensions.
                    // Bs[SM_ROWS_B][TK] = Bs[80][16]. Each row can hold one K iteration.
                    // So Bs[k][ty][...] — but Bs is [80][16], not [16][80][16].
                    // I need Bs[k][tx*TN+j] = B[t*TK+ty][t*TK+k+tx*TN+j].
                    // But that means each tx=0..15 thread loads 4 elements for each k=0..15,
                    // total 64 elements per thread. With SM_ROWS_B=80 rows and TK=16 cols,
                    // Bs[80][16] has 1280 elements. With TY=16 threads, each thread handles 4 columns,
                    // total 16*4 = 64 elements. That's only 1/1280 = 5% utilization!
                    //
                    // Wrong approach. Let me rethink.
                }
            }
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) {
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int row = outRow + i;
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int col = outCol + j;
                C[row * N + col] = acc[i][j];
            }
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
