#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=32  => 512 threads
// Tile:   32x32 shared-memory tiles
// Register tile: TM=1, TN=2 (each thread computes 2 output elements)
//
// Thread (tx,ty) computes C[by*32+ty][bx*32+tx*2] and C[by*32+ty][bx*32+tx*2+1]
//
// As[TK][TY] — broadcast: all TX threads with same ty write same value
// Bs[TK][TG] — coalesced: each (k,col) loaded by exactly 1 thread
//
// Global loads: coalesced within warp (16 consecutive columns per warp)
// ============================================================================

#define TG  32
#define TK  32
#define TX  16
#define TY  32
#define BLK (TX * TY)  // 512
#define TM  1          // = TG / TY
#define TN  2          // = TG / TX

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TK][TY];
    __shared__ float Bs[TK][TG];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx * TN;
    const int outRow = by * TG + ty * TM;
    const int numTiles = (N + TK - 1) / TK;

    float acc0 = 0.0f;
    float acc1 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile (broadcast: 16 threads write same value) ---
        for (int k = 0; k < TK; ++k)
            As[k][ty] = A[(outRow) * N + (t * TK + k)];

        // --- Load B tile (coalesced: 16 threads × 2 cols = 32 consecutive) ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            Bs[k][tx * TN + 0] = B[(t * TK + k) * N + (outCol + 0)];
            Bs[k][tx * TN + 1] = B[(t * TK + k) * N + (outCol + 1)];
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a = As[k][ty];
            acc0 += a * Bs[k][tx * TN + 0];
            acc1 += a * Bs[k][tx * TN + 1];
        }

        __syncthreads();
    }

    if (outRow < N && outCol + 0 < N)
        C[outRow * N + outCol + 0] = acc0;
    if (outCol + 1 < N)
        C[outRow * N + outCol + 1] = acc1;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
