#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads (4 blocks/SM, good occupancy)
// Tile:   64x64 output tile per block
// K-tile: 16 (4 K-splits: 64/16 = 4 syncs)
// Register tile: TM=4, TN=4 (each thread computes 16 output elements)
//
// Shared memory: As[64][64], Bs[64][64] with 1-element padding to reduce
// bank conflicts (TX=16 => 16-way conflict on 32-bank GPU)
//
// Memory access pattern:
//   - Global loads: coalesced (TX=16 threads load 16 consecutive columns)
//   - Shared reads: As[k][ty*TM+i] broadcast to TX=16 threads in warp
//                   Bs[k][tx*TN+j] broadcast to TY=16 threads in warp
//   - Each K iteration: TX=16 MAC broadcasts, TY=16 BS broadcasts
//   - Total MACs per thread per K-tile: TM*TN*TK = 4*4*16 = 256
//   - Total MACs per block per K-tile: 256 threads * 256 MACs = 65536
//   - Block total: 65536 * 4 K-tiles = 262144 MACs = 64*64*64 (correct!)
// ============================================================================

#define TG  64        // Output tile edge
#define TK  16        // K-tile size
#define TX  16        // Block dim X
#define TY  16        // Block dim Y
#define TM  4         // = TG / TY  (rows per thread)
#define TN  4         // = TG / TX  (cols per thread)
#define SM_PAD 1      // Shared memory row padding to break bank conflicts

__shared__ float As[TK][TG + SM_PAD];
__shared__ float Bs[TK][TG + SM_PAD];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outCol = bx * TG + tx;
    const int outRow = by * TG + ty;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: each thread computes TM×TN = 16 elements
    float acc00 = 0.0f, acc01 = 0.0f, acc02 = 0.0f, acc03 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f, acc12 = 0.0f, acc13 = 0.0f;
    float acc20 = 0.0f, acc21 = 0.0f, acc22 = 0.0f, acc23 = 0.0f;
    float acc30 = 0.0f, acc31 = 0.0f, acc32 = 0.0f, acc33 = 0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile ---
        // Thread (tx,ty) handles rows outRow+0..outRow+3,
        // loading column t*TK+tx from each row.
        // As[k][ty*TM+i] = A[outRow+ty*TM+i][t*TK+k]  where k=tx.
        // So As[tx][ty*TM+i] = A[outRow+ty*TM+i][t*TK+tx] for i=0..3.
        // TX=16 threads, each loads 1 column => 16 consecutive columns total.
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = outRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile ---
        // Thread (tx,ty) handles columns outCol+0..outCol+3,
        // loading row t*TK+ty.
        // Bs[k][tx*TN+j] = B[t*TK+k][outCol+tx*TN+j]  where k=tx.
        // But outCol = bx*TG+tx. So columns are t*TK+tx*TN+j = t*TK+tx*4+j.
        // Wait, that's wrong. Let me reconsider.
        //
        // Thread (tx,ty) computes output rows outRow+0..outRow+3 and
        // columns outCol+0..outCol+3.
        // outCol = bx*64+tx. So cols = bx*64+tx, bx*64+tx+1, bx*64+tx+2, bx*64+tx+3.
        // Bs[k][tx*TN+j] stores B[t*TK+k][outCol+tx*TN+j].
        // For tx=0: j=0..3 => cols t*TK+0, t*TK+1, t*TK+2, t*TK+3.
        // For tx=1: j=0..3 => cols t*TK+4, t*TK+5, t*TK+6, t*TK+7.
        // ...
        // For tx=15: j=0..3 => cols t*TK+60, t*TK+61, t*TK+62, t*TK+63.
        // That's 64 columns total, correct!
        //
        // Bs[tx][tx*TN+j] is wrong — tx is both a row index and a column offset.
        // Let me fix: Bs[k+tx][tx*TN+j] = B[t*TK+k+tx][outCol+tx*TN+j]? No.
        //
        // The B tile for K-tile t has:
        //   rows: t*TK .. t*TK+TK-1 = t*TK .. t*TK+15
        //   cols: bx*TG .. bx*TG+TG-1 = bx*64 .. bx*64+63
        // Thread (tx,ty) loads:
        //   rows: t*TK+ty (single row)
        //   cols: outCol+tx*TN+j = bx*64+tx+tx*4+j
        // That's wrong: bx*64+tx + tx*4 = bx*64+5*tx, not bx*64+tx+4*j.
        //
        // Let me rethink. Thread (tx,ty) computes C[rows][cols] where:
        //   rows = outRow + ty*TM + i = by*64 + ty*4 + i  for i=0..3
        //   cols = outCol + tx*TN + j = bx*64 + tx*4 + j  for j=0..3
        // Wait, outCol = bx*64 + tx. So cols = bx*64+tx + tx*4+j = bx*64 + 5*tx + j.
        // For tx=0: cols bx*64+0..bx*64+3. For tx=1: cols bx*64+5..bx*64+8. Gap!
        // That's not contiguous! The bug is: outCol + tx*TN should be bx*TG + tx*TN.
        // But outCol = bx*TG + tx. So I should use bx*TG + tx*TN instead.
        //
        // Let me fix: outCol = bx * TG (block-start), and each thread handles
        // cols outCol + tx*TN + j. Then:
        // tx=0: cols 0..3, tx=1: cols 4..7, ..., tx=15: cols 60..63.
        // Perfect!

        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int bRow = t * TK + ty;
            int bCol = bx * TG + tx * TN + j;
            Bs[tx][tx * TN + j] = (bRow < N && bCol < N)
                                  ? B[bRow * N + bCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0 = As[k][ty * TM + 0];
            float a1 = As[k][ty * TM + 1];
            float a2 = As[k][ty * TM + 2];
            float a3 = As[k][ty * TM + 3];
            float b0 = Bs[k][tx * TN + 0];
            float b1 = Bs[k][tx * TN + 1];
            float b2 = Bs[k][tx * TN + 2];
            float b3 = Bs[k][tx * TN + 3];
            acc00 += a0 * b0; acc01 += a0 * b1; acc02 += a0 * b2; acc03 += a0 * b3;
            acc10 += a1 * b0; acc11 += a1 * b1; acc12 += a1 * b2; acc13 += a1 * b3;
            acc20 += a2 * b0; acc21 += a2 * b1; acc22 += a2 * b2; acc23 += a2 * b3;
            acc30 += a3 * b0; acc31 += a3 * b1; acc32 += a3 * b2; acc33 += a3 * b3;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow + TM - 1 < N && outCol + TN - 1 < N) {
        C[(outRow + 0) * N + (bx * TG + 0)] = acc00;
        C[(outRow + 0) * N + (bx * TG + 1)] = acc01;
        C[(outRow + 0) * N + (bx * TG + 2)] = acc02;
        C[(outRow + 0) * N + (bx * TG + 3)] = acc03;
        C[(outRow + 1) * N + (bx * TG + 0)] = acc10;
        C[(outRow + 1) * N + (bx * TG + 1)] = acc11;
        C[(outRow + 1) * N + (bx * TG + 2)] = acc12;
