#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=16  => 512 threads
// Tile:   64x64 output tile per block
// K-tile: 64 (1 sync per block!)
// Register tile: TM=4, TN=2 (each thread computes 8 elements)
//
// Stride-2 loading: each thread handles 2 consecutive As/Bs rows/cols
// As[k][ty*TM+i] = A[...][t*TK+k] — k=0..63 loaded by 32 threads (stride 2)
// Bs[k][tx*TN+j] = B[...][blockCol+tx*TN+j] — k=0..63 loaded by 16 threads (stride 2)
//
// Shared memory: As[TK][TM*TY] = As[64][64], Bs[TK][TN*TX] = Bs[64][64]
// ============================================================================

#define TG  64        // Output tile edge
#define TK  64        // K-tile size (1 sync per block)
#define TX  32        // Block dim X
#define TY  16        // Block dim Y
#define TM  4         // = TG / TY  (rows per thread)
#define TN  2         // = TG / TX  (cols per thread)

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTiles = (N + TK - 1) / TK;

    // Accumulator: TM×TN = 4×2 = 8 elements per thread
    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;
    float acc20 = 0.0f, acc21 = 0.0f;
    float acc30 = 0.0f, acc31 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile (stride-2: each thread loads 2 As rows) ---
        #pragma unroll
        for (int i2 = 0; i2 < 2; ++i2) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                int aRow = blockRow + ty * TM + i;
                int aCol = t * TK + 2 * tx + i2;
                if (aRow < N && aCol < N)
                    As[2 * tx + i2][ty * TM + i] = A[aRow * N + aCol];
                else
                    As[2 * tx + i2][ty * TM + i] = 0.0f;
            }
        }

        // --- Load B tile (stride-2: each thread loads 2 Bs rows) ---
        #pragma unroll
        for (int j2 = 0; j2 < 2; ++j2) {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int bRow = t * TK + 2 * ty + j2;
                int bCol = blockCol + tx * TN + j;
                if (bRow < N && bCol < N)
                    Bs[2 * ty + j2][tx * TN + j] = B[bRow * N + bCol];
                else
                    Bs[2 * ty + j2][tx * TN + j] = 0.0f;
            }
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        // Thread (tx,ty) computes C rows blockRow+ty*4..blockRow+ty*4+3
        //                 cols blockCol+tx*2..blockCol+tx*2+1
        // acc[i][j] += sum_{k=0}^{63} As[k][ty*4+i] * Bs[k][tx*2+j]
        // As[k][ty*4+i] = A[blockRow+ty*4+i][t*TK+k]
        // Bs[k][tx*2+j] = B[t*TK+k][blockCol+tx*2+j]
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float b0 = Bs[k][tx * TN + 0];
            float b1 = Bs[k][tx * TN + 1];
            acc00 += As[k][ty * TM + 0] * b0;
            acc01 += As[k][ty * TM + 0] * b1;
            acc10 += As[k][ty * TM + 1] * b0;
            acc11 += As[k][ty * TM + 1] * b1;
            acc20 += As[k][ty * TM + 2] * b0;
            acc21 += As[k][ty * TM + 2] * b1;
            acc30 += As[k][ty * TM + 3] * b0;
            acc31 += As[k][ty * TM + 3] * b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int row = outRow + i;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int col = outCol + j;
            if (row < N && col < N)
                C[row * N + col] = (i == 0 && j == 0) ? acc00 :
                                   (i == 0 && j == 1) ? acc01 :
                                   (i == 1 && j == 0) ? acc10 :
                                   (i == 1 && j == 1) ? acc11 :
                                   (i == 2 && j == 0) ? acc20 :
                                   (i == 2 && j == 1) ? acc21 :
                                   (i == 3 && j == 0) ? acc30 : acc31;
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
