// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads (max per block)
// Tile:   64x64 output tile per block
// K-tile: 64 (1 sync per block!)
// Register tile: TM=2, TN=2 (each thread computes 4 elements)
//
// As[k][ty*TM+i] = A[...][t*TK+k] — k=0..63 loaded by 32 threads (stride-2)
// Bs[k][tx*TN+j] = B[...][blockCol+tx*TN+j] — k=0..63 loaded by 32 threads (stride-2)
//
// Shared memory: As[TK][TM*TY] = As[64][64], Bs[TK][TN*TX] = Bs[64][64]
// ============================================================================

#define TG  64        // Output tile edge
#define TK  64        // K-tile size
#define TX  32        // Block dim X
#define TY  32        // Block dim Y
#define TM  2         // = TG / TY
#define TN  2         // = TG / TX

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTiles = (N + TK - 1) / TK;

    // Accumulator: TM×TN = 2×2 = 4 elements per thread
    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile (stride-2: each thread loads 2 consecutive As rows) ---
        #pragma unroll
        for (int i2 = 0; i2 < 2; ++i2) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                int aRow = blockRow + ty * TM + i;
                int aCol = t * TK + 2 * tx + i2;
                if (aRow < N && aCol < N)
                    As[2 * tx + i2][ty * TM + i] = A[aRow * N + aCol];
                else
                    As[2 * tx + i2][ty * TM + i] = 0.0f;
            }
        }

        // --- Load B tile (stride-2: each thread loads 2 consecutive Bs rows) ---
        #pragma unroll
        for (int j2 = 0; j2 < 2; ++j2) {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int bRow = t * TK + 2 * ty + j2;
                int bCol = blockCol + tx * TN + j;
                if (bRow < N && bCol < N)
                    Bs[2 * ty + j2][tx * TN + j] = B[bRow * N + bCol];
                else
                    Bs[2 * ty + j2][tx * TN + j] = 0.0f;
            }
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float b0 = Bs[k][tx * TN + 0];
            float b1 = Bs[k][tx * TN + 1];
            acc00 += As[k][ty * TM + 0] * b0;
            acc01 += As[k][ty * TM + 0] * b1;
            acc10 += As[k][ty * TM + 1] * b0;
            acc11 += As[k][ty * TM + 1] * b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int row = outRow + i;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int col = outCol + j;
            if (row < N && col < N)
                C[row * N + col] = (i == 0 && j == 0) ? acc00 :
                                   (i == 0 && j == 1) ? acc01 :
                                   (i == 1 && j == 0) ? acc10 : acc11;
        }
    }
}

