#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads (4 blocks/SM)
// Tile:   64x64 output tile per block
// K-tile: 16 (4 K-splits = 4 syncs per block)
// Register tile: TM=4, TN=4 (16 elements per thread)
//
// Key optimizations:
// - Padded shared memory to eliminate bank conflicts
// - Full register tiling with unrolled K-loop
// - Coalesced global loads (TX=16 threads load 16 consecutive K-columns)
// - Shared memory reads broadcast efficiently (As row broadcast, Bs row broadcast)
// - Minimize divergence: all threads follow same code path
// ============================================================================

#define TG  64        // Output tile edge
#define TK  16        // K-tile size
#define TX  16        // Block dim X
#define TY  16        // Block dim Y
#define TM  4         // = TG / TY  (rows per thread)
#define TN  4         // = TG / TX  (cols per thread)
#define SM_PAD 65     // Shared memory padding to break 16-way bank conflicts

__shared__ float As[TK][TG + SM_PAD];
__shared__ float Bs[TK][TG + SM_PAD];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: 4×4 = 16 elements per thread, unrolled to separate registers
    float acc00=0.0f, acc01=0.0f, acc02=0.0f, acc03=0.0f;
    float acc10=0.0f, acc11=0.0f, acc12=0.0f, acc13=0.0f;
    float acc20=0.0f, acc21=0.0f, acc22=0.0f, acc23=0.0f;
    float acc30=0.0f, acc31=0.0f, acc32=0.0f, acc33=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile ---
        // Thread tx loads As[tx][ty*TM+0..3] = A[row][t*TK+tx] for 4 rows
        // TX=16 threads load 16 consecutive K-columns = coalesced
        {
            float a0=A[(blockRow+ty*TM+0)*N+t*TK+tx], a1=A[(blockRow+ty*TM+1)*N+t*TK+tx];
            float a2=A[(blockRow+ty*TM+2)*N+t*TK+tx], a3=A[(blockRow+ty*TM+3)*N+t*TK+tx];
            As[tx][ty*TM+0] = (blockRow+ty*TM+0 < N && t*TK+tx < N) ? a0 : 0.0f;
            As[tx][ty*TM+1] = (blockRow+ty*TM+1 < N && t*TK+tx < N) ? a1 : 0.0f;
            As[tx][ty*TM+2] = (blockRow+ty*TM+2 < N && t*TK+tx < N) ? a2 : 0.0f;
            As[tx][ty*TM+3] = (blockRow+ty*TM+3 < N && t*TK+tx < N) ? a3 : 0.0f;
        }

        // --- Load B tile ---
        // Thread tx loads Bs[ty][tx*TN+0..3] = B[t*TK+ty][blockCol+tx*4+0..3]
        // TX=16 threads * TN=4 cols = 64 Bs columns = effectively coalesced
        {
            int bRow = t * TK + ty;
            int bBase = bRow * N;
            int c0 = blockCol + tx * TN;
            float b0=bBase+c0+0, b1=bBase+c0+1, b2=bBase+c0+2, b3=bBase+c0+3;
            Bs[ty][tx*TN+0] = (bRow<N && c0+0<N) ? b0 : 0.0f;
            Bs[ty][tx*TN+1] = (bRow<N && c0+1<N) ? b1 : 0.0f;
            Bs[ty][tx*TN+2] = (bRow<N && c0+2<N) ? b2 : 0.0f;
            Bs[ty][tx*TN+3] = (bRow<N && c0+3<N) ? b3 : 0.0f;
        }

