// As[TK][TM*TY+1] = As[16][65] — row-major, 1-element row padding
// Bs[TK][TN*TX+1] = As[16][65]
//
// Thread (tx,ty) computes C[blockRow+ty*4+0..3][blockCol+tx*4+0..3]
// ============================================================================

