{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads (4 blocks/SM)
// Tile:   64x64 output tile per block
// K-tile: 16 (4 K-splits = 4 syncs)
// Register tile: TM=4, TN=4 (16 elements per thread)
//
// As[TK][TG+1] — 1-element row padding to avoid 16-way bank conflicts
// Bs[TK][TG+1]
//
// Fully unrolled K-loop for maximum ILP
// ============================================================================

#define TG  64
#define TK  16
#define TX  16
#define TY  16
#define TM  4
#define TN  4

__shared__ float As[TK][TG + 1];
__shared__ float Bs[TK][TG + 1];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f, acc02=0.0f, acc03=0.0f;
    float acc10=0.0f, acc11=0.0f, acc12=0.0f, acc13=0.0f;
    float acc20=0.0f, acc21=0.0f, acc22=0.0f, acc23=0.0f;
    float acc30=0.0f, acc31=0.0f, acc32=0.0f, acc33=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile ---
        // Thread tx=0..15: As[k][ty*4+i] = A[row][t*TK+k]
        // TX=16 threads load 16 K-columns = coalesced
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            int aCol = t * TK + k;
            float a0 = A[(blockRow+ty*TM+0)*N + aCol];
            float a1 = A[(blockRow+ty*TM+1)*N + aCol];
            float a2 = A[(blockRow+ty*TM+2)*N + aCol];
            float a3 = A[(blockRow+ty*TM+3)*N + aCol];
            As[k][ty*TM+0] = (blockRow+ty*TM+0<N && aCol<N) ? a0 : 0.0f;
            As[k][ty*TM+1] = (blockRow+ty*TM+1<N && aCol<N) ? a1 : 0.0f;
            As[k][ty*TM+2] = (blockRow+ty*TM+2<N && aCol<N) ? a2 : 0.0f;
            As[k][ty*TM+3] = (blockRow+ty*TM+3<N && aCol<N) ? a3 : 0.0f;
        }

        // --- Load B tile ---
        // Thread tx=0..15: Bs[k][tx*4+j] = B[t*TK+k][blockCol+tx*4+j]
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            int bRow = t * TK + k;
            int bIdx = bRow * N;
            int c0 = blockCol + tx * TN;
            float b0 = B[bIdx + c0 + 0];
            float b1 = B[bIdx + c0 + 1];
            float b2 = B[bIdx + c0 + 2];
            float b3 = B[bIdx + c0 + 3];
            Bs[k][tx*TN+0] = (bRow<N && c0+0<N) ? b0 : 0.0f;
            Bs[k][tx*TN+1] = (bRow<N && c0+1<N) ? b1 : 0.0f;
            Bs[k][tx*TN+2] = (bRow<N && c0+2<N) ? b2 : 0.0f;
            Bs[k][tx*TN+3] = (bRow<N && c0+3<N) ? b3 : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate (fully unrolled K loop) ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1], a2=As[k][ty*TM+2], a3=As[k][ty*TM+3];
            float b0=Bs[k][tx*TN+0], b1=Bs[k][tx*TN+1], b2=Bs[k][tx*TN+2], b3=Bs[k][tx*TN+3];
            acc00+=a0*b0; acc01+=a0*b1; acc02+=a0*b2; acc03+=a0*b3;
            acc10+=a1*b0; acc11+=a1*b1; acc12+=a1*b2; acc13+=a1*b3;
            acc20+=a2*b0; acc21+=a2*b1; acc22+=a2*b2; acc23+=a2*b3;
            acc30+=a3*b0; acc31+=a3*b1; acc32+=a3*b2; acc33+=a3*b3;
        }

        __syncthreads();
    }

    // --- Store result (individual element boundary checks) ---
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int row = outRow + i;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int col = outCol + j;
            if (row < N && col < N)
                C[row * N + col] = acc[i][j];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
