{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads (max occupancy)
// Tile:   64x64 output tile per block
// K-tile: 32 (2 K-splits = 2 syncs per block)
// Register tile: TM=2, TN=2 (4 elements per thread)
//
// As[TK][TM*TY+1] = As[32][65] — 1-element padding
// Bs[TK][TN*TX+1] = Bs[32][65]
//
// TX=32 threads load TK=32 K-columns (1 per thread) = fully coalesced
// TY=32 threads load TK=32 K-rows (1 per thread) = fully coalesced
// ============================================================================

#define TG  64
#define TK  32
#define TX  32
#define TY  32
#define TM  2
#define TN  2

__shared__ float As[TK][TM * TY + 1];
__shared__ float Bs[TK][TN * TX + 1];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=32 threads, TK=32 cols: 1 col per thread) ---
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=32 threads, TK=32 rows: 1 row per thread) ---
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int bRow = t * TK + ty;
            int bCol = blockCol + tx * TN + j;
            Bs[ty][tx * TN + j] = (bRow < N && bCol < N)
                                  ? B[bRow * N + bCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0 = As[k][ty * TM + 0];
            float a1 = As[k][ty * TM + 1];
            float b0 = Bs[k][tx * TN + 0];
            float b1 = Bs[k][tx * TN + 1];
            acc00 += a0 * b0;
            acc01 += a0 * b1;
            acc10 += a1 * b0;
            acc11 += a1 * b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
    if (outRow + 1 < N && outCol < N) C[(outRow + 1) * N + outCol] = acc10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow + 1) * N + outCol + 1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
