#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads
// Tile:   64x64 output tile per block
// K-tile: 64 (1 K-split = 1 sync per block)
// Register tile: TM=4, TN=4 (16 elements per thread)
//
// As[TK][TM*TY+1] — 1-element padding to break bank conflicts
// Bs[TK][TN*TX+1]
//
// Thread (tx,ty) computes C[blockRow+ty*4+0..3][blockCol+tx*4+0..3]
// ============================================================================

#define TG  64
#define TK  64
#define TX  16
#define TY  16
#define TM  4
#define TN  4

__shared__ float As[TK][TM * TY + 1];
__shared__ float Bs[TK][TN * TX + 1];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f, acc02=0.0f, acc03=0.0f;
    float acc10=0.0f, acc11=0.0f, acc12=0.0f, acc13=0.0f;
    float acc20=0.0f, acc21=0.0f, acc22=0.0f, acc23=0.0f;
    float acc30=0.0f, acc31=0.0f, acc32=0.0f, acc33=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=16 threads × 16 cols = TK=64 cols, stride=4) ---
        for (int i2 = 0; i2 < 4; ++i2) {
            int k = t * TK + 4 * tx + i2;
            float a0, a1, a2, a3;
            a0 = A[(blockRow+ty*TM+0)*N + k];
            a1 = A[(blockRow+ty*TM+1)*N + k];
            a2 = A[(blockRow+ty*TM+2)*N + k];
            a3 = A[(blockRow+ty*TM+3)*N + k];
            As[k][ty*TM+0] = (blockRow+ty*TM+0<N && k<N) ? a0 : 0.0f;
            As[k][ty*TM+1] = (blockRow+ty*TM+1<N && k<N) ? a1 : 0.0f;
            As[k][ty*TM+2] = (blockRow+ty*TM+2<N && k<N) ? a2 : 0.0f;
            As[k][ty*TM+3] = (blockRow+ty*TM+3<N && k<N) ? a3 : 0.0f;
        }

        // --- Load B tile (TY=16 threads × 16 rows = TK=64 rows, stride=4) ---
        for (int j2 = 0; j2 < 4; ++j2) {
            int k = t * TK + 4 * ty + j2;
            int bIdx = k * N;
            float b0, b1, b2, b3;
            b0 = B[bIdx + blockCol + tx*TN + 0];
            b1 = B[bIdx + blockCol + tx*TN + 1];
            b2 = B[bIdx + blockCol + tx*TN + 2];
            b3 = B[bIdx + blockCol + tx*TN + 3];
            Bs[k][tx*TN+0] = (k<N && blockCol+tx*TN+0<N) ? b0 : 0.0f;
            Bs[k][tx*TN+1] = (k<N && blockCol+tx*TN+1<N) ? b1 : 0.0f;
            Bs[k][tx*TN+2] = (k<N && blockCol+tx*TN+2<N) ? b2 : 0.0f;
            Bs[k][tx*TN+3] = (k<N && blockCol+tx*TN+3<N) ? b3 : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1], a2=As[k][ty*TM+2], a3=As[k][ty*TM+3];
            float b0=Bs[k][tx*TN+0], b1=Bs[k][tx*TN+1], b2=Bs[k][tx*TN+2], b3=Bs[k][tx*TN+3];
            acc00+=a0*b0; acc01+=a0*b1; acc02+=a0*b2; acc03+=a0*b3;
            acc10+=a1*b0; acc11+=a1*b1; acc12+=a1*b2; acc13+=a1*b3;
            acc20+=a2*b0; acc21+=a2*b1; acc22+=a2*b2; acc23+=a2*b3;
            acc30+=a3*b0; acc31+=a3*b1; acc32+=a3*b2; acc33+=a3*b3;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
    if (outRow < N && outCol + 2 < N) C[outRow * N + outCol + 2] = acc02;
    if (outRow < N && outCol + 3 < N) C[outRow * N + outCol + 3] = acc03;
    if (outRow + 1 < N && outCol < N) C[(outRow+1)*N + outCol] = acc10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow+1)*N + outCol + 1] = acc11;
    if (outRow + 1 < N && outCol + 2 < N) C[(outRow+1)*N + outCol + 2] = acc12;
    if (outRow + 1 < N && outCol + 3 < N) C[(outRow+1)*N + outCol + 3] = acc13;
    if (outRow + 2 < N && outCol < N) C[(outRow+2)*N + outCol] = acc20;
    if (outRow + 2 < N && outCol + 1 < N) C[(outRow+2)*N + outCol + 1] = acc21;
    if (outRow + 2 < N && outCol + 2 < N) C[(outRow+2)*N + outCol + 2] = acc22;
    if (outRow + 2 < N && outCol + 3 < N) C[(outRow+2)*N + outCol + 3] = acc23;
    if (outRow + 3 < N && outCol < N) C[(outRow+3)*N + outCol] = acc30;
    if (outRow + 3 < N && outCol + 1 < N) C[(outRow+3)*N + outCol + 1] = acc31;
    if (outRow + 3 < N && outCol + 2 < N) C[(outRow+3)*N + outCol + 2] = acc32;
    if (outRow + 3 < N && outCol + 3 < N) C[(outRow+3)*N + outCol + 3] = acc33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
