#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=16  => 512 threads
// Tile:   64x64 output tile per block
// K-tile: 32 (1 K-split = 1 sync)
// Register tile: TM=4, TN=2 (8 elements per thread)
//
// Shared memory: As[TK][TM*TY] = As[32][64], Bs[TK][TN*TX] = Bs[32][64]
//
// TX=32 threads load TK/2=16 cols (stride-2), TY=16 threads load TK=32 rows
// ============================================================================

#define TG  64
#define TK  32
#define TX  32
#define TY  16
#define TM  4
#define TN  2

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: TM×TN = 4×2 = 8 elements
    float acc00=0.0f, acc01=0.0f;
    float acc10=0.0f, acc11=0.0f;
    float acc20=0.0f, acc21=0.0f;
    float acc30=0.0f, acc31=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=32 threads × TM=4 rows = 128, but TK=32 cols) ---
        // TX=32 threads each load 1 column: tx=0..15 loads col 4*tx+0..3
        // Wait, we need 32 columns for TK=32, with 32 threads = 1 col/thread
        // Thread tx loads column t*TK + tx for TM rows
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=16 threads × 1 row = 16 rows) ---
        // Only 16 rows loaded, but we need 32 rows. TX=32 threads split into
        // TY=16 groups of 2, each group loads 2 rows.
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int bRow = t * TK + ty;
            int bCol = blockCol + tx * TN + j;
            Bs[ty][tx * TN + j] = (bRow < N && bCol < N)
                                  ? B[bRow * N + bCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1], a2=As[k][ty*TM+2], a3=As[k][ty*TM+3];
            float b0=Bs[k][tx*TN+0], b1=Bs[k][tx*TN+1];
            acc00+=a0*b0; acc01+=a0*b1;
            acc10+=a1*b0; acc11+=a1*b1;
            acc20+=a2*b0; acc21+=a2*b1;
            acc30+=a3*b0; acc31+=a3*b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
    if (outRow + 1 < N && outCol < N) C[(outRow+1)*N + outCol] = acc10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow+1)*N + outCol + 1] = acc11;
    if (outRow + 2 < N && outCol < N) C[(outRow+2)*N + outCol] = acc20;
    if (outRow + 2 < N && outCol + 1 < N) C[(outRow+2)*N + outCol + 1] = acc21;
    if (outRow + 3 < N && outCol < N) C[(outRow+3)*N + outCol] = acc30;
    if (outRow + 3 < N && outCol + 1 < N) C[(outRow+3)*N + outCol + 1] = acc31;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
