#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads (max per SM)
// Tile:   64x64 output tile per block
// K-tile: 64 (1 K-split = 1 sync per block)
// Register tile: TM=2, TN=2 (4 elements per thread)
//
// TX=32 threads load 2 K-columns each (TX and TX+32) = 64 cols total
// TY=32 threads load 2 K-rows each (TY and TY+32) = 64 rows total
//
// As[TK][TM*TY] = As[64][64], Bs[TK][TN*TX] = Bs[64][64]
// ============================================================================

#define TG  64
#define TK  64
#define TX  32
#define TY  32
#define TM  2
#define TN  2

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f;
    float acc10=0.0f, acc11=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=32 threads, 2 K-columns each = 64 cols total) ---
        // Phase 1: load columns 0..31 (TX threads, coalesced)
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }
        // Phase 2: load columns 32..63 (TX threads → As[32..63][...], coalesced)
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx + TK / 2;
            As[tx + TK / 2][ty * TM + i] = (aRow < N && aCol < N)
                                            ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=32 threads, 2 K-rows each = 64 rows total) ---
        // Phase 1: load rows 0..31 (TY threads, coalesced)
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int bRow = t * TK + ty;
            int bCol = blockCol + tx * TN + j;
            Bs[ty][tx * TN + j] = (bRow < N && bCol < N)
                                  ? B[bRow * N + bCol] : 0.0f;
        }
        // Phase 2: load rows 32..63
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int bRow = t * TK + ty + TK / 2;
            int bCol = blockCol + tx * TN + j;
            Bs[ty + TK / 2][tx * TN + j] = (bRow < N && bCol < N)
                                           ? B[bRow * N + bCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0 = As[k][ty * TM + 0];
            float a1 = As[k][ty * TM + 1];
            float b0 = Bs[k][tx * TN + 0];
            float b1 = Bs[k][tx * TN + 1];
            acc00 += a0 * b0;
            acc01 += a0 * b1;
            acc10 += a1 * b0;
            acc11 += a1 * b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
    if (outRow + 1 < N && outCol < N) C[(outRow+1) * N + outCol] = acc10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow+1) * N + outCol + 1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
