#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=16, TY=16  => 256 threads
// Tile:   64x64 output tile per block
// K-tile: 64 (1 K-split = 1 sync per block)
// Register tile: TM=8, TN=2 (16 elements per thread)
//
// Shared memory: As[TK][TM*TY] = As[64][128], Bs[TK][TN*TX] = Bs[64][32]
// As[TK][TM*TY] = 64×128 = 32KB (max for 4 blocks/SM)
// Bs[TK][TN*TX] = 64×32 = 8KB
//
// TX=16 threads load 4 K-columns each = 64 cols total
// TY=16 threads load 4 K-rows each = 64 rows total
// ============================================================================

#define TG  64
#define TK  64
#define TX  16
#define TY  16
#define TM  8
#define TN  2

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    // Accumulator: TM×TN = 8×2 = 16 elements
    float acc00=0.0f, acc01=0.0f;
    float acc10=0.0f, acc11=0.0f;
    float acc20=0.0f, acc21=0.0f;
    float acc30=0.0f, acc31=0.0f;
    float acc40=0.0f, acc41=0.0f;
    float acc50=0.0f, acc51=0.0f;
    float acc60=0.0f, acc61=0.0f;
    float acc70=0.0f, acc71=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=16 threads × 4 cols = 64 cols) ---
        #pragma unroll
        for (int i2 = 0; i2 < 4; ++i2) {
            int k = 4 * tx + i2;
            float a0=A[(blockRow+ty*TM+0)*N+(t*TK+k)], a1=A[(blockRow+ty*TM+1)*N+(t*TK+k)];
            float a2=A[(blockRow+ty*TM+2)*N+(t*TK+k)], a3=A[(blockRow+ty*TM+3)*N+(t*TK+k)];
            float a4=A[(blockRow+ty*TM+4)*N+(t*TK+k)], a5=A[(blockRow+ty*TM+5)*N+(t*TK+k)];
            float a6=A[(blockRow+ty*TM+6)*N+(t*TK+k)], a7=A[(blockRow+ty*TM+7)*N+(t*TK+k)];
            int cond = (t*TK+k < N);
            As[k][ty*TM+0] = (blockRow+ty*TM+0<N && cond) ? a0 : 0.0f;
            As[k][ty*TM+1] = (blockRow+ty*TM+1<N && cond) ? a1 : 0.0f;
            As[k][ty*TM+2] = (blockRow+ty*TM+2<N && cond) ? a2 : 0.0f;
            As[k][ty*TM+3] = (blockRow+ty*TM+3<N && cond) ? a3 : 0.0f;
            As[k][ty*TM+4] = (blockRow+ty*TM+4<N && cond) ? a4 : 0.0f;
            As[k][ty*TM+5] = (blockRow+ty*TM+5<N && cond) ? a5 : 0.0f;
            As[k][ty*TM+6] = (blockRow+ty*TM+6<N && cond) ? a6 : 0.0f;
            As[k][ty*TM+7] = (blockRow+ty*TM+7<N && cond) ? a7 : 0.0f;
        }

        // --- Load B tile (TY=16 threads × 4 rows = 64 rows) ---
        #pragma unroll
        for (int j2 = 0; j2 < 4; ++j2) {
            int k = 4 * ty + j2;
            int bIdx = (t*TK+k)*N;
            float b0=B[bIdx+blockCol+tx*TN+0], b1=B[bIdx+blockCol+tx*TN+1];
            int cond = (t*TK+k < N);
            Bs[k][tx*TN+0] = (cond && blockCol+tx*TN+0<N) ? b0 : 0.0f;
            Bs[k][tx*TN+1] = (cond && blockCol+tx*TN+1<N) ? b1 : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate (unrolled) ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float b0=Bs[k][0], b1=Bs[k][1];
            acc00 += As[k][ty*TM+0] * b0; acc01 += As[k][ty*TM+0] * b1;
            acc10 += As[k][ty*TM+1] * b0; acc11 += As[k][ty*TM+1] * b1;
            acc20 += As[k][ty*TM+2] * b0; acc21 += As[k][ty*TM+2] * b1;
            acc30 += As[k][ty*TM+3] * b0; acc31 += As[k][ty*TM+3] * b1;
            acc40 += As[k][ty*TM+4] * b0; acc41 += As[k][ty*TM+4] * b1;
            acc50 += As[k][ty*TM+5] * b0; acc51 += As[k][ty*TM+5] * b1;
            acc60 += As[k][ty*TM+6] * b0; acc61 += As[k][ty*TM+6] * b1;
            acc70 += As[k][ty*TM+7] * b0; acc71 += As[k][ty*TM+7] * b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    for (int i = 0; i < TM; ++i) {
        int r = outRow + i;
        if (r < N) {
            C[r * N + outCol] = (i==0) ? acc00 : (i==1) ? acc10 :
                                (i==2) ? acc20 : (i==3) ? acc30 :
                                (i==4) ? acc40 : (i==5) ? acc50 :
                                (i==6) ? acc60 : acc70;
            if (outCol + 1 < N)
                C[r * N + outCol + 1] = (i==0) ? acc01 : (i==1) ? acc11 :
                                         (i==2) ? acc21 : (i==3) ? acc31 :
                                         (i==4) ? acc41 : (i==5) ? acc51 :
                                         (i==6) ? acc61 : acc71;
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
