#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=16  => 512 threads (16 warps per block)
// Tile:   64x64 output tile per block
// K-tile: 64 (1 sync per block)
// Register tile: TM=4, TN=2 (8 elements per thread)
//
// TX=32 threads per warp = 1 full warp per ty row.
// Coalesced global loads (32 consecutive addresses per warp).
// 16 warps per block, 16 warps per SM with 2 blocks = excellent occupancy.
// ============================================================================

#define TG  64
#define TK  64
#define TX  32
#define TY  16
#define TM  4
#define TN  2

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f;
    float acc10=0.0f, acc11=0.0f;
    float acc20=0.0f, acc21=0.0f;
    float acc30=0.0f, acc31=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=32 threads per warp, coalesced) ---
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=16 threads per warp, coalesced) ---
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int bRow = t * TK + ty;
            int bCol = blockCol + tx * TN + j;
            Bs[ty][tx * TN + j] = (bRow < N && bCol < N)
                                  ? B[bRow * N + bCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1], a2=As[k][ty*TM+2], a3=As[k][ty*TM+3];
            float b0=Bs[k][tx*TN+0], b1=Bs[k][tx*TN+1];
            acc00+=a0*b0; acc01+=a0*b1;
            acc10+=a1*b0; acc11+=a1*b1;
            acc20+=a2*b0; acc21+=a2*b1;
            acc30+=a3*b0; acc31+=a3*b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
