{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=64, TY=16  => 1024 threads (max block size)
// Tile:   64x64 output tile per block
// K-tile: 64 (1 sync per block)
// Register tile: TM=4, TN=1 (4 elements per thread)
//
// TX=64 threads load 64 K-columns of 4 rows = fully coalesced (2 warps)
// TY=16 threads load 64 K-rows of 64 cols = each thread loads 4 K-rows
//
// As[TK][TM*TY] = As[64][64], Bs[TK][TN*TX] = Bs[64][64]
// 16KB SMEM each = 32KB total. Max 5 blocks/SM (80KB < 164KB)
// But 1024 threads/block: max 2 blocks/SM (2048/1024=2).
// Occupancy: 2*1024/2048 = 100%.
// ============================================================================

#define TG  64
#define TK  64
#define TX  64
#define TY  16
#define TM  4
#define TN  1

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc0=0.0f, acc1=0.0f, acc2=0.0f, acc3=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=64 threads, coalesced: 2 warps) ---
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=16 threads * TX=64 = 1024 threads for 64*64 elements) ---
        // Each thread loads Bs[k][tx] for k = ty * TK / TY + offset.
        // Actually: we need to load Bs[k][tx] for ALL k. Each thread handles
        // a subset: k = ty * (TK/TY) + 0..(TK/TY-1).
        // With TY=16, TK=64: TK/TY = 4. Each thread loads 4 K rows.
        #pragma unroll
        for (int k2 = 0; k2 < TK / TY; ++k2) {
            int k = ty * (TK / TY) + k2;
            int bRow = t * TK + k;
            int bCol = blockCol + tx * TN;
            Bs[k][tx] = (bRow < N && bCol < N)
                        ? B[bRow * N + bCol] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1], a2=As[k][ty*TM+2], a3=As[k][ty*TM+3];
            float b=Bs[k][tx];
            acc0+=a0*b;
            acc1+=a1*b;
            acc2+=a2*b;
            acc3+=a3*b;
        }

        __syncthreads();
    }

    // --- Store result ---
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int r = outRow + i;
        int c = outCol;
        if (r < N && c < N) {
            float val;
            if (i == 0) val = acc0;
            else if (i == 1) val = acc1;
            else if (i == 2) val = acc2;
            else val = acc3;
            C[r * N + c] = val;
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
