// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=64, TY=16  => 1024 threads (max per block)
// Tile:   128x128 output tile per block
// K-tile: 64 (1 K-split = 1 sync per block)
// Register tile: TM=8, TN=2 (16 elements per thread)
//
// Shared memory: As[TK][TM*TY] = As[64][128] = 32KB
//                Bs[TK][TN*TX] = Bs[64][128] = 32KB
// Total SMEM: 64KB. 2 blocks/SM max. 100% occupancy.
//
// TX=64 threads load 64 K-columns (1 col/thread) = fully coalesced
// TY=16 threads each load 4 K-rows (TK/TY=4 rows/thread)
// ============================================================================

#define TG  128
#define TK  64
#define TX  64
#define TY  16
#define TM  8
#define TN  2

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f;
    float acc10=0.0f, acc11=0.0f;
    float acc20=0.0f, acc21=0.0f;
    float acc30=0.0f, acc31=0.0f;
    float acc40=0.0f, acc41=0.0f;
    float acc50=0.0f, acc51=0.0f;
    float acc60=0.0f, acc61=0.0f;
    float acc70=0.0f, acc71=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=64 threads, 64 K-columns, 1 col/thread, coalesced) ---
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=16 threads, each loads 4 K-rows = 64 total) ---
        #pragma unroll
        for (int k2 = 0; k2 < TK / TY; ++k2) {
            int k = ty * (TK / TY) + k2;
            int bRow = t * TK + k;
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int bCol = blockCol + tx * TN + j;
                Bs[k][tx * TN + j] = (bRow < N && bCol < N)
                                     ? B[bRow * N + bCol] : 0.0f;
            }
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float b0 = Bs[k][tx * TN + 0];
            float b1 = Bs[k][tx * TN + 1];
            acc00 += As[k][ty * TM + 0] * b0; acc01 += As[k][ty * TM + 0] * b1;
            acc10 += As[k][ty * TM + 1] * b0; acc11 += As[k][ty * TM + 1] * b1;
            acc20 += As[k][ty * TM + 2] * b0; acc21 += As[k][ty * TM + 2] * b1;
            acc30 += As[k][ty * TM + 3] * b0; acc31 += As[k][ty * TM + 3] * b1;
            acc40 += As[k][ty * TM + 4] * b0; acc41 += As[k][ty * TM + 4] * b1;
            acc50 += As[k][ty * TM + 5] * b0; acc51 += As[k][ty * TM + 5] * b1;
            acc60 += As[k][ty * TM + 6] * b0; acc61 += As[k][ty * TM + 6] * b1;
            acc70 += As[k][ty * TM + 7] * b0; acc71 += As[k][ty * TM + 7] * b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
    if (outRow + 1 < N && outCol < N) C[(outRow+1) * N + outCol] = acc10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow+1) * N + outCol + 1] = acc11;
    if (outRow + 2 < N && outCol < N) C[(outRow+2) * N + outCol] = acc20;
    if (outRow + 2 < N && outCol + 1 < N) C[(outRow+2) * N + outCol + 1] = acc21;
    if (outRow + 3 < N && outCol < N) C[(outRow+3) * N + outCol] = acc30;
    if (outRow + 3 < N && outCol + 1 < N) C[(outRow+3) * N + outCol + 1] = acc31;
