    if (outRow + 4 < N && outCol + 1 < N) C[(outRow+4) * N + outCol + 1] = acc41;
    if (outRow + 5 < N && outCol < N) C[(outRow+5) * N + outCol] = acc50;
    if (outRow + 5 < N && outCol + 1 < N) C[(outRow+5) * N + outCol + 1] = acc51;
    if (outRow + 6 < N && outCol < N) C[(outRow+6) * N + outCol] = acc60;
    if (outRow + 6 < N && outCol + 1 < N) C[(outRow+6) * N + outCol + 1] = acc61;
    if (outRow + 7 < N && outCol < N) C[(outRow+7) * N + outCol] = acc70;
    if (outRow + 7 < N && outCol + 1 < N) C[(outRow+7) * N + outCol + 1] = acc71;
}

