            float b2 = B[bIdx + blockCol + tx*TN + 2], b3 = B[bIdx + blockCol + tx*TN + 3];
            Bs[k][tx*TN+0] = (cond && blockCol+tx*TN+0<N) ? b0 : 0.0f;
            Bs[k][tx*TN+1] = (cond && blockCol+tx*TN+1<N) ? b1 : 0.0f;
            Bs[k][tx*TN+2] = (cond && blockCol+tx*TN+2<N) ? b2 : 0.0f;
            Bs[k][tx*TN+3] = (cond && blockCol+tx*TN+3<N) ? b3 : 0.0f;
        }

