            int gk = t * TK + k;
            int cond = (gk < N);
            int bIdx = gk * N;
            float b0 = B[bIdx + blockCol + tx*TN + 0], b1 = B[bIdx + blockCol + tx*TN + 1];
            float b2 = B[bIdx + blockCol + tx*TN + 2], b3 = B[bIdx + blockCol + tx*TN + 3];
            Bs[k][tx*TN+0] = (cond && blockCol+tx*TN+0<N) ? b0 : 0.0f;
            Bs[k][tx*TN+1] = (cond && blockCol+tx*TN+1<N) ? b1 : 0.0f;
            Bs[k][tx*TN+2] = (cond && blockCol+tx*TN+2<N) ? b2 : 0.0f;
            Bs[k][tx*TN+3] = (cond && blockCol+tx*TN+3<N) ? b3 : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate (unrolled) ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1], a2=As[k][ty*TM+2], a3=As[k][ty*TM+3];
            float b0=Bs[k][tx*TN+0], b1=Bs[k][tx*TN+1], b2=Bs[k][tx*TN+2], b3=Bs[k][tx*TN+3];
            acc00+=a0*b0; acc01+=a0*b1; acc02+=a0*b2; acc03+=a0*b3;
            acc10+=a1*b0; acc11+=a1*b1; acc12+=a1*b2; acc13+=a1*b3;
            acc20+=a2*b0; acc21+=a2*b1; acc22+=a2*b2; acc23+=a2*b3;
            acc30+=a3*b0; acc31+=a3*b1; acc32+=a3*b2; acc33+=a3*b3;
        }

        __syncthreads();
    }

