// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=32  => 1024 threads (max per block)
// Tile:   64x64 output tile per block
// K-tile: 32 (2 K-splits = 2 syncs per block)
// Register tile: TM=2, TN=2 (4 elements per thread)
//
// TX=32 threads load 32 cols of 64 rows each (2 cols/thread, coalesced)
// TY=32 threads load 32 rows of 64 cols each (2 cols/thread, coalesced)
//
// Shared memory: As[TK][TM*TY] = As[32][64], Bs[TK][TN*TX] = Bs[32][64]
// 8KB each = 16KB total. 10 blocks/SM possible.
// 1024 threads per SM = 50% occupancy.
// ============================================================================

#define TG  64
#define TK  32
#define TX  32
#define TY  32
#define TM  2
#define TN  2

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f;
    float acc10=0.0f, acc11=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=32 threads × 2 cols = 64 cols, TM=2 rows each) ---
        #pragma unroll
        for (int i2 = 0; i2 < 2; ++i2) {
            int k = 2 * tx + i2;
            int gk = t * TK + k;
            int cond = (gk < N);
            As[k][ty*TM+0] = (blockRow+ty*TM+0<N && cond) ? A[(blockRow+ty*TM+0)*N+gk] : 0.0f;
            As[k][ty*TM+1] = (blockRow+ty*TM+1<N && cond) ? A[(blockRow+ty*TM+1)*N+gk] : 0.0f;
        }

        // --- Load B tile (TY=32 threads × 2 rows = 64 rows, TN=2 cols each) ---
        #pragma unroll
        for (int j2 = 0; j2 < 2; ++j2) {
            int k = 2 * ty + j2;
            int gk = t * TK + k;
            int cond = (gk < N);
            int bIdx = gk * N;
            float b0 = B[bIdx + blockCol + tx*TN + 0], b1 = B[bIdx + blockCol + tx*TN + 1];
            Bs[k][tx*TN+0] = (cond && blockCol+tx*TN+0<N) ? b0 : 0.0f;
            Bs[k][tx*TN+1] = (cond && blockCol+tx*TN+1<N) ? b1 : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float a0=As[k][ty*TM+0], a1=As[k][ty*TM+1];
            float b0=Bs[k][tx*TN+0], b1=Bs[k][tx*TN+1];
            acc00 += a0*b0; acc01 += a0*b1;
            acc10 += a1*b0; acc11 += a1*b1;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc00;
    if (outRow < N && outCol + 1 < N) C[outRow * N + outCol + 1] = acc01;
    if (outRow + 1 < N && outCol < N) C[(outRow+1) * N + outCol] = acc10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow+1) * N + outCol + 1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
