#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40)
//
// Block:  TX=32, TY=16  => 512 threads
// Tile:   64x64 output tile per block
// K-tile: 64 (1 sync per block)
// Register tile: TM=4, TN=2 (8 elements per thread)
//
// Double buffering: load K=0..31 while computing K=32..63 (and vice versa).
// 2 banks of shared memory. Each thread uses 8 acc registers.
//
// Shared memory: As0/As1[64][64] + Bs0/Bs1[64][64] = 64KB each pair = 128KB total
// This limits to 1 block/SM (164KB limit). 512 threads/SM = 25% occupancy.
// But double buffering hides memory latency.
//
// Alternative: use TX=16, TY=16 for smaller SMEM:
// Double buffer: As0/As1[64][65] + Bs0/Bs1[64][65] = 16KB each = 64KB total
// 100KB/64KB = 1 block/SM, 256 threads/SM = 12.5% occupancy.
//
// Let's go with 3-way double buffering (load K+1 while computing K, preload K+2):
// Actually for 1 sync per block, we only have 2 K-tiles. So double buffering
// just gives us: compute K0, load K1 simultaneously.
//
// Better approach: TX=16, TY=16, TG=128, TK=64
// TM=8, TN=8. Each thread computes 64 elements.
// 256 threads, 2 blocks/SM (64KB SMEM with ping-pong)
// 2 K-splits: load K0, compute K0. Load K1, compute K1.
// With double buffer: compute K0, load K1 simultaneously.
// ============================================================================

#define TG  64
#define TK  64
#define TX  16
#define TY  16
#define TM  4
#define TN  4

__shared__ float As[2 * TK][TM * TY + 1];
__shared__ float Bs[2 * TK][TN * TX + 1];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc00=0.0f, acc01=0.0f, acc02=0.0f, acc03=0.0f;
    float acc10=0.0f, acc11=0.0f, acc12=0.0f, acc13=0.0f;
    float acc20=0.0f, acc21=0.0f, acc22=0.0f, acc23=0.0f;
    float acc30=0.0f, acc31=0.0f, acc32=0.0f, acc33=0.0f;

    // Double buffer: ping-pong between 0 and 1
    // t=0: load tile 0, compute nothing
    // t=1: load tile 1 + compute tile 0
    // t=2: compute tile 1 (already loaded from previous)

    for (int t = 0; t < numTilesK; ++t) {
        int bank = t & 1;  // 0 or 1
        int prevBank = (t - 1) & 1;
        bool isFirst = (t == 0);

        // --- Load current tile ---
        #pragma unroll
        for (int i2 = 0; i2 < 4; ++i2) {
            int k = 4 * tx + i2;
            int gk = t * TK + k;
            int cond = (gk < N);
            As[bank*TK + k][ty*TM+0] = (blockRow+ty*TM+0<N && cond) ? A[(blockRow+ty*TM+0)*N+gk] : 0.0f;
            As[bank*TK + k][ty*TM+1] = (blockRow+ty*TM+1<N && cond) ? A[(blockRow+ty*TM+1)*N+gk] : 0.0f;
            As[bank*TK + k][ty*TM+2] = (blockRow+ty*TM+2<N && cond) ? A[(blockRow+ty*TM+2)*N+gk] : 0.0f;
            As[bank*TK + k][ty*TM+3] = (blockRow+ty*TM+3<N && cond) ? A[(blockRow+ty*TM+3)*N+gk] : 0.0f;
        }

        #pragma unroll
        for (int j2 = 0; j2 < 4; ++j2) {
            int k = 4 * ty + j2;
            int gk = t * TK + k;
            int cond = (gk < N);
            int bIdx = gk * N;
            float b0 = B[bIdx+blockCol+tx*TN+0], b1 = B[bIdx+blockCol+tx*TN+1];
            float b2 = B[bIdx+blockCol+tx*TN+2], b3 = B[bIdx+blockCol+tx*TN+3];
            Bs[bank*TK + k][tx*TN+0] = (cond && blockCol+tx*TN+0<N) ? b0 : 0.0f;
            Bs[bank*TK + k][tx*TN+1] = (cond && blockCol+tx*TN+1<N) ? b1 : 0.0f;
            Bs[bank*TK + k][tx*TN+2] = (cond && blockCol+tx*TN+2<N) ? b2 : 0.0f;
            Bs[bank*TK + k][tx*TN+3] = (cond && blockCol+tx*TN+3<N) ? b3 : 0.0f;
        }

        // --- Compute previous tile (if not first) ---
        if (!isFirst) {
            __syncthreads();
            int pBank = prevBank;
            #pragma unroll
            for (int k = 0; k < TK; ++k) {
                float a0=As[pBank*TK+ty*TM+0], a1=As[pBank*TK+ty*TM+1];
                float a2=As[pBank*TK+ty*TM+2], a3=As[pBank*TK+ty*TM+3];
                float b0=Bs[pBank*TK][tx*TN+0], b1=Bs[pBank*TK][tx*TN+1];
                float b2=Bs[pBank*TK][tx*TN+2], b3=Bs[pBank*TK][tx*TN+3];
                // Need to unroll k loop... but we can't easily because
                // As[k] and Bs[k] change with k. Let me use a loop.
            }
        }

        __syncthreads();
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
