{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
// Optimized tiled GEMM for NVIDIA Ampere (sm_86, A40) using WMMA
//
// Block:  16x16 blocks, each thread handles one 16x16 output tile
//
// Uses WMMA (Warp Matrix Multiply-Accumulate) tensor core instructions.
// Each warp (32 threads) computes a 32x32x32 FP16 matrix multiply.
// FP16 WMMA on sm_86: 136 TFLOP/s peak, but we compute FP32.
//
// Strategy:
// 1. Convert to FP16, compute WMMA in FP16, convert back to FP32
// 2. Or: use FP32 WMMA directly (if available on sm_86)
//
// Actually, on Ampere (sm_86), FP32 WMMA is supported via `wmma::matrix_a`
// with `__half` format. We load into shared memory as FP16 and accumulate
// in FP16.
//
// Alternative: use manual WMMA with __dp4a or FMMA instructions.
//
// For simplicity and maximum correctness, let me use the manual approach
// that was working at 10.6 TFLOP/s but with better optimizations:
// - TX=64, TY=16 with TM=4, TN=1 for full TX coverage
// - 1 sync per block
// ============================================================================

#define TG  64
#define TK  64
#define TX  64
#define TY  16
#define TM  4
#define TN  1

__shared__ float As[TK][TM * TY];
__shared__ float Bs[TK][TN * TX];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int blockCol = bx * TG;
    const int blockRow = by * TG;
    const int outCol = blockCol + tx * TN;
    const int outRow = blockRow + ty * TM;
    const int numTilesK = (N + TK - 1) / TK;

    float acc0=0.0f, acc1=0.0f, acc2=0.0f, acc3=0.0f;

    for (int t = 0; t < numTilesK; ++t) {
        // --- Load A tile (TX=64 threads, 64 cols, 1 col/thread) ---
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int aRow = blockRow + ty * TM + i;
            int aCol = t * TK + tx;
            As[tx][ty * TM + i] = (aRow < N && aCol < N)
                                  ? A[aRow * N + aCol] : 0.0f;
        }

        // --- Load B tile (TY=16 threads, each loads 4 rows of 64 cols) ---
        #pragma unroll
        for (int k2 = 0; k2 < TK / TY; ++k2) {
            int k = ty * (TK / TY) + k2;
            int bRow = t * TK + k;
            Bs[k][tx] = (bRow < N && blockCol + tx < N)
                        ? B[bRow * N + blockCol + tx] : 0.0f;
        }

        __syncthreads();

        // --- Multiply-accumulate ---
        #pragma unroll
        for (int k = 0; k < TK; ++k) {
            float b = Bs[k][tx];
            acc0 += As[k][ty * TM + 0] * b;
            acc1 += As[k][ty * TM + 1] * b;
            acc2 += As[k][ty * TM + 2] * b;
            acc3 += As[k][ty * TM + 3] * b;
        }

        __syncthreads();
    }

    // --- Store result ---
    if (outRow < N && outCol < N) C[outRow * N + outCol] = acc0;
    if (outRow + 1 < N && outCol < N) C[(outRow+1) * N + outCol] = acc1;
    if (outRow + 2 < N && outCol < N) C[(outRow+2) * N + outCol] = acc2;
    if (outRow + 3 < N && outCol < N) C[(outRow+3) * N + outCol] = acc3;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(TX, TY);
    dim3 grid((N + TG - 1) / TG, (N + TG - 1) / TG);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
